<script setup lang="ts">import{computed,onMounted,ref}from'vue';import DefaultLayout from'@/layouts/DefaultLayout.vue';import LoadingSpinner from'@/components/ui/LoadingSpinner.vue';import BaseButton from'@/components/ui/BaseButton.vue';import{useApi}from'@/composables/useApi';import type{ApiResponse,Certificate,Enrollment}from'@/types';const api=useApi(),items=ref<Enrollment[]>([]),error=ref('');const completed=computed(()=>items.value.filter(x=>x.status==='COMPLETED').length);async function load(){try{const r=await api.get<ApiResponse<Enrollment[]>>('/enrollments/me');items.value=r.data||[]}catch(e){error.value=e instanceof Error?e.message:'Không thể tải khóa học'}}async function issue(item:Enrollment){try{await api.post<ApiResponse<Certificate>>(`/courses/${item.courseId}/certificates`);location.href='/certificates'}catch(e){alert(e instanceof Error?e.message:'Chưa đủ điều kiện cấp chứng chỉ')}}onMounted(load)</script>
<template><DefaultLayout><main class="mx-auto max-w-7xl px-4 py-10"><div class="mb-8 flex items-end justify-between"><div><h1 class="text-3xl font-black">Khóa học của tôi</h1><p class="mt-2 text-slate-500">{{items.length}} khóa học · {{completed}} hoàn thành</p></div><RouterLink to="/orders" class="font-bold text-purple-600">Đơn hàng</RouterLink></div><LoadingSpinner v-if="api.loading.value"/><p v-else-if="error" class="text-red-600">{{error}}</p><div v-else-if="!items.length" class="rounded-2xl bg-white p-12 text-center text-slate-500 dark:bg-slate-900">Bạn chưa đăng ký khóa học nào. <RouterLink to="/courses" class="font-bold text-purple-600">Khám phá khóa học</RouterLink></div><div v-else class="grid gap-5 md:grid-cols-2"><article v-for="item in items" :key="item.id" class="rounded-2xl border bg-white p-5 shadow-sm dark:border-slate-800 dark:bg-slate-900"><img v-if="item.course.thumbnailUrl" :src="item.course.thumbnailUrl" class="h-44 w-full rounded-xl object-cover"><h2 class="mt-4 text-xl font-bold">{{item.course.title}}</h2><div class="mt-4 h-2 overflow-hidden rounded-full bg-slate-100"><div class="h-full bg-purple-600" :style="{width:`${item.progressPercent}%`}"></div></div><p class="mt-2 text-sm text-slate-500">{{Math.round(item.progressPercent)}}% hoàn thành</p><RouterLink :to="`/learn/${item.courseId}`"><BaseButton :full-width="true">{{item.progressPercent?'Tiếp tục học':'Bắt đầu học'}}</BaseButton></RouterLink><BaseButton v-if="item.status==='COMPLETED'" variant="outline" :full-width="true" @click="issue(item)">Nhận chứng chỉ</BaseButton></article></div></main></DefaultLayout></template>
